	@SuppressWarnings("unchecked")
	private static List<?> invokeList(Method list) throws ReflectiveOperationException {
		return (List<?>) list.invoke(null);
	}

	private static List<String> stateNames(List<?> states) throws ReflectiveOperationException {
		return states.stream().map(state -> invokeString(state, "name")).toList();
	}

	private static List<String> stateSortKeys(List<?> states) throws ReflectiveOperationException {
		return states.stream()
				.map(state -> invokeString(state, "group") + "\u0000" + invokeString(state, "name"))
				.toList();
	}

	private static Object stateByName(List<?> states, String name) throws ReflectiveOperationException {
		return states.stream()
				.filter(state -> name.equals(invokeString(state, "name")))
				.findFirst()
				.orElseThrow();
	}

	private static String invokeString(Object target, String method) {
		try {
			return (String) target.getClass().getMethod(method).invoke(target);
		} catch (ReflectiveOperationException e) {
			throw new AssertionError(e);
		}
	}

	private static boolean booleanValue(Object target, String method) throws ReflectiveOperationException {
		return (boolean) target.getClass().getMethod(method).invoke(target);
	}

	private static void assertLiveFlag(String className, String property) throws Exception {
		String previous = System.getProperty(property);
		try {
			Class<?> owner = Class.forName(className);
			Method enabled = owner.getDeclaredMethod("enabled");
			enabled.setAccessible(true);
			System.setProperty(property, "false");
			assertThat(enabled.invoke(null)).isEqualTo(false);
			System.setProperty(property, "true");
			assertThat(enabled.invoke(null)).isEqualTo(true);
		} finally {
			restore(property, previous);
		}
	}

	private static void restore(String property, String previous) {
		if (previous == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, previous);
		}
	}
